module cryptarithm_solver (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] puzzle_char,\n    input puzzle_valid,\n    output reg [7:0] result_char,\n    output reg result_valid,\n    output reg done,\n    output reg impossible\n);\n\nlocalparam MAX_PUZZLE_LEN = 20;\nlocalparam MAX_LETTERS = 8;\nlocalparam CLK_TIMEOUT = 32'd10000;\n\nlocalparam [3:0] IDLE = 4'd0;\nlocalparam [3:0] PARSE = 4'd1;\nlocalparam [3:0] SOLVE = 4'd2;\nlocalparam [3:0] OUTPUT = 4'd3;\nlocalparam [3:0] DONE_ST = 4'd4;\n\nreg [3:0] state, next_state;\nreg [7:0] puzzle [0:MAX_PUZZLE_LEN-1];\nreg [5:0] puzzle_len;\nreg [7:0] letters [0:MAX_LETTERS-1];\nreg [3:0] letter_count;\nreg [3:0] leading_letters [0:MAX_LETTERS-1];\nreg [3:0] current_letter_idx;\nreg [3:0] digit_assignment [0:MAX_LETTERS-1];\nreg [3:0] output_idx;\nreg [31:0] timeout_counter;\nreg [31:0] computed_num1, computed_num2, computed_num3;\n\nalways @(posedge clk or negedge rst_n) begin\n    integer i;\n    if (!rst_n) begin\n        state <= IDLE;\n        puzzle_len <= 6'd0;\n        letter_count <= 4'd0;\n        current_letter_idx <= 4'd0;\n        output_idx <= 4'd0;\n        result_valid <= 1'b0;\n        done <= 1'b0;\n        impossible <= 1'b0;\n        timeout_counter <= 32'd0;\n        for (i = 0; i < MAX_PUZZLE_LEN; i = i + 1) begin\n            puzzle[i] <= 8'd0;\n        end\n        for (i = 0; i < MAX_LETTERS; i = i + 1) begin\n            letters[i] <= 8'd0;\n            digit_assignment[i] <= 4'd0;\n            leading_letters[i] <= 1'b0;\n        end\n    end else begin\n        state <= next_state;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    puzzle_len <= 6'd0;\n                    letter_count <= 4'd0;\n                    current_letter_idx <= 4'd0;\n                    output_idx <= 4'd0;\n                    result_valid <= 1'b0;\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    timeout_counter <= 32'd0;\n                    \n                    for (i = 0; i < MAX_LETTERS; i = i + 1) begin\n                        digit_assignment[i] <= 4'd0;\n                        leading_letters[i] <= 1'b0;\n                    end\n                end\n            end\n            \n            PARSE: begin\n                if (puzzle_valid && puzzle_len < MAX_PUZZLE_LEN) begin\n                    puzzle[puzzle_len] <= puzzle_char;\n                    puzzle_len <= puzzle_len + 6'd1;\n                    \n                    if (puzzle_char >= 8'h41 && puzzle_char <= 8'h5A) begin\n                        \n                        // Track leading characters\n                        if (puzzle_len == 6'd0 ||\n                            (puzzle_len > 6'd0 && \n                             (puzzle[puzzle_len-1] == 8'h2B || \n                              puzzle[puzzle_len-1] == 8'h3D))) begin\n                            leading_letters[letter_count] <= 1'b1;\n                        end\n                        \n                        // Check if letter exists\n                        reg found;\n                        found = 1'b0;\n                        for (i = 0; i < letter_count; i = i + 1) begin\n                            if (letters[i] == puzzle_char) begin\n                                found = 1'b1;\n                            end\n                        end\n                        if (~found && letter_count < MAX_LETTERS) begin\n                            letters[letter_count] <= puzzle_char;\n                            letter_count <= letter_count + 4'd1;\n                        end\n                    end\n                end\n            end\n            \n            SOLVE: begin\n                timeout_counter <= timeout_counter + 32'd1;\n                \n                if (current_letter_idx < letter_count) begin\n                    if (digit_assignment[current_letter_idx] < 4'd9) begin\n                        digit_assignment[current_letter_idx] <= \n                            digit_assignment[current_letter_idx] + 4'd1;\n                    end else begin\n                        digit_assignment[current_letter_idx] <= 4'd0;\n                        current_letter_idx <= current_letter_idx + 4'd1;\n                    end\n                end\n                \n                // Compute numbers when all letters assigned\n                if (current_letter_idx == letter_count) begin\n                    {computed_num1, computed_num2, computed_num3} <= compute_equation();\n                    current_letter_idx <= 4'd0;\n                end\n            end\n            \n            OUTPUT: begin\n                if (output_idx < puzzle_len) begin\n                    result_valid <= 1'b1;\n                    output_idx <= output_idx + 4'd1;\n                    if (puzzle[output_idx] >= 8'h41 && puzzle[output_idx] <= 8'h5A) begin\n                        for (i = 0; i < letter_count; i = i + 1) begin\n                            if (letters[i] == puzzle[output_idx]) begin\n                                result_char <= 8'h30 + digit_assignment[i];\n                            end\n                        end\n                    end else begin\n                        result_char <= puzzle[output_idx];\n                    end\n                end else begin\n                    result_valid <= 1'b0;\n                end\n            end\n            \n            DONE_ST: begin\n                done <= 1'b1;\n            end\n        endcase\n    end\nend\n\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: if (start) next_state = PARSE;\n        PARSE: if (~puzzle_valid || puzzle_len >= MAX_PUZZLE_LEN) \n                 next_state = (letter_count > 4'd0 && letter_count <= MAX_LETTERS) ? SOLVE : DONE_ST;\n        SOLVE: begin\n            if (timeout_counter >= CLK_TIMEOUT) begin\n                impossible = 1'b1;\n                next_state = DONE_ST;\n            end else if (current_letter_idx == letter_count && \n                     computed_num1 + computed_num2 == computed_num3 && \n                     check_leading_zeros()) begin\n                next_state = OUTPUT;\n            end else if (&digit_assignment[letter_count-1:0]) begin\n                impossible = 1'b1;\n                next_state = DONE_ST;\n            end\n        end\n        OUTPUT: if (output_idx >= puzzle_len) next_state = DONE_ST;\n        DONE_ST: next_state = IDLE;\n        default: next_state = IDLE;\n    endcase\nend\n\nfunction reg check_leading_zeros;\n    integer i;\n    begin\n        check_leading_zeros = 1'b1;\n        for (i = 0; i < letter_count; i = i + 1) begin\n            if (leading_letters[i] && digit_assignment[i] == 4'd0) begin\n                check_leading_zeros = 1'b0;\n            end\n        end\n    end\nendfunction\n\nfunction [95:0] compute_equation;\n    integer i;\n    reg [31:0] num1, num2, num3;\n    reg [31:0] current;\n    reg in_num1, in_num2, in_num3;\n    begin\n        num1 = 32'd0;\n        num2 = 32'd0;\n        num3 = 32'd0;\n        current = 32'd0;\n        in_num1 = 1'b1;\n        in_num2 = 1'b0;\n        in_num3 = 1'b0;\n        \n        for (i = 0; i < puzzle_len; i = i + 1) begin\n            if (puzzle[i] == 8'h2B) begin  // '+'\n                if (in_num1) begin\n                    num1 = current;\n                    current = 32'd0;\n                    in_num1 = 1'b0;\n                    in_num2 = 1'b1;\n                end\n            end else if (puzzle[i] == 8'h3D) begin  // '='\n                if (in_num2) begin\n                    num2 = current;\n                    current = 32'd0;\n                    in_num2 = 1'b0;\n                    in_num3 = 1'b1;\n                end\n            end else if (puzzle[i] >= 8'h41 && puzzle[i] <= 8'h5A) begin\n                for (integer j = 0; j < letter_count; j = j + 1) begin\n                    if (letters[j] == puzzle[i]) begin\n                        current = current * 10 + digit_assignment[j];\n                    end\n                end\n            end\n        end\n        \n        if (in_num3) num3 = current;\n        compute_equation = {num1, num2, num3};\n    end\nendfunction\n\nendmodule